(()=>{const reduce=matchMedia('(prefers-reduced-motion: reduce)'),heroTrack=document.querySelector('.hero-track'),hero=document.querySelector('.hero'),copy=document.querySelector('.hero-copy'),track=document.querySelector('.chapter-track'),sticky=document.querySelector('.chapter-sticky'),tabs=[...document.querySelectorAll('.chapter-tabs a')],visuals=[...document.querySelectorAll('.chapter-visual')],copies=[...document.querySelectorAll('.chapter-copy')];let current=-1,scheduled=false;const clamp=n=>Math.max(0,Math.min(1,n));function activate(index,progress){if(index!==current){current=index;tabs.forEach((tab,i)=>{tab.classList.toggle('active',i===index);if(i===index)tab.setAttribute('aria-current','step');else tab.removeAttribute('aria-current')});visuals.forEach((v,i)=>{v.classList.toggle('active',i===index);v.inert=i!==index;v.setAttribute('aria-hidden',String(i!==index))});copies.forEach((v,i)=>{v.classList.toggle('active',i===index);v.inert=i!==index;v.setAttribute('aria-hidden',String(i!==index))});document.getElementById('chapter-count').textContent=String(index+1).padStart(2,'0')+' — 04'}tabs.forEach((t,i)=>{t.querySelector('i').style.width=(i<index?100:i===index?progress*100:0)+'%'});document.getElementById('chapter-progress').style.width=((index+progress)/4*100)+'%'}
function update(){scheduled=false;const hr=heroTrack.getBoundingClientRect(),heroRange=heroTrack.offsetHeight-hero.offsetHeight;const hp=reduce.matches?0:clamp(-hr.top/Math.max(1,heroRange));hero.style.setProperty('--hero-scroll',hp);copy.style.transform=`translateY(${-hp*90}px)`;copy.style.opacity=String(1-hp*.8);window.bathstoreProduct?.setScroll(hp);document.getElementById('hero-progress').style.width=(hp*100)+'%';document.getElementById('hero-phase').textContent=hp<.33?'01 / THE FORM':hp<.68?'02 / THE FINISH':'03 / EVERY ANGLE';if(!reduce.matches){const r=track.getBoundingClientRect(),top=parseFloat(getComputedStyle(sticky).top)||88,range=track.offsetHeight-sticky.offsetHeight;const p=clamp((top-r.top)/Math.max(1,range)),n=Math.min(3,Math.floor(p*4));activate(n,p===1?1:p*4-n)}}function queue(){if(!scheduled){scheduled=true;requestAnimationFrame(update)}}tabs.forEach((tab,i)=>tab.addEventListener('click',e=>{e.preventDefault();if(reduce.matches){activate(i,1)}else{const top=parseFloat(getComputedStyle(sticky).top)||88,range=track.offsetHeight-sticky.offsetHeight;window.scrollTo({top:scrollY+track.getBoundingClientRect().top-top+range*(i/4+.015),behavior:'smooth'})}history.replaceState(null,'',tab.getAttribute('href'))}));addEventListener('scroll',queue,{passive:true});addEventListener('resize',queue);reduce.addEventListener('change',()=>{activate(0,1);queue()});activate(0,0);update();})();
// Preserve deep-link navigation in layouts that use chapter selection.
(()=>{const ids=['consultation','vision','curation-step','proposal-step'];document.querySelectorAll('a[href]').forEach(link=>{const id=link.getAttribute('href').slice(1),index=ids.indexOf(id);if(index<0||link.closest('.chapter-tabs'))return;link.addEventListener('click',event=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches){event.preventDefault();document.querySelectorAll('.chapter-tabs a')[index].click();document.querySelector('.chapter-track').scrollIntoView({behavior:'auto',block:'start'})}})})})();
(()=>{const buttons=[...document.querySelectorAll('[data-finish]')];const names={chrome:'Polished chrome',nickel:'Brushed nickel',graphite:'Graphite'};buttons.forEach(button=>button.addEventListener('click',()=>{const finish=button.dataset.finish;buttons.forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button))});document.querySelector('.finish-room').dataset.selected=finish;document.getElementById('finish-caption').textContent='Selected study: '+names[finish];document.getElementById('hero-finish-label').textContent=names[finish].toUpperCase()+' · ORIGINAL DESIGN';window.bathstoreProduct?.setFinish(finish)}))})();
